    public static Geometry For(WorkspacePage page) => page switch
    {
        WorkspacePage.Plan => Plan,
        WorkspacePage.Agents => Agents,
        WorkspacePage.GitChanges => Changes,
        WorkspacePage.Diff => Edits,
        WorkspacePage.Skill => Skills,
        WorkspacePage.FilePreview => File,
        WorkspacePage.Browser => Browser,
        _ => Workspace,
    };

    public static Geometry For(WorkspaceCategory category) => category switch
    {
        WorkspaceCategory.Plan => Plan,
        WorkspaceCategory.Agents => Agents,
        WorkspaceCategory.Changes => Changes,
        WorkspaceCategory.Files => Files,
        WorkspaceCategory.Edits => Edits,
        WorkspaceCategory.Skills => Skills,
        WorkspaceCategory.Links => Links,
        WorkspaceCategory.Sources => Sources,
        WorkspaceCategory.Messages => Messages,
        WorkspaceCategory.Activity => Activity,
        WorkspaceCategory.Browser => Browser,
        _ => Workspace,
    };

    public static Geometry For(WorkspaceActivityKind kind) => kind switch
    {
        WorkspaceActivityKind.Intent => Intent,
        WorkspaceActivityKind.Search => Search,
        WorkspaceActivityKind.Subagent => Agents,
        WorkspaceActivityKind.Question => Question,
        WorkspaceActivityKind.Error => Error,
        _ => Activity,
    };

    // Two zero-length strokes pin the bounds to the grid corners; they draw nothing.
    private static Geometry Glyph(string pathData) => Geometry.Parse("F1 M0 0h0M20 20h0" + pathData);
}
